def int_sqrt(n: int) -> int:
    if n < 2:
        return n

    x = n
    y = (x + 1) // 2
    while y < x:
        x = y
        y = (x + n // x) // 2
    return x

def longest_run(xs: list[int]) -> int:
    if not xs:
        return 0

    max_run = 1
    current_run = 1

    for i in range(1, len(xs)):
        if xs[i] == xs[i-1]:
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 1

    return max_run

